@@ -88,7 +98,7 @@ class ReservationServiceTest {

         assertEquals(ReservationStatus.CONFIRMED, service.find(reservation.id()).status());
         List<Message> sent = sentMessages.all();
-        assertEquals(1, sent.size());
+        assertEquals(3, sent.size());
         assertEquals("EMAIL", sent.get(0).channel());
         assertEquals("ana@example.com", sent.get(0).to());
         assertEquals("Reserva confirmada - Pousada Maré Alta", sent.get(0).subject());
@@ -102,7 +112,7 @@ class ReservationServiceTest {
         service.confirm(reservation.id());

         assertEquals(ErrorCode.OPERATION_NOT_ALLOWED, errorOf(() -> service.confirm(reservation.id())));
-        assertEquals(1, sentMessages.all().size());
+        assertEquals(3, sentMessages.all().size());
     }

     @Test
@@ -159,4 +169,64 @@ class ReservationServiceTest {
     void anUnknownReservationIsNotFound() {
         assertEquals(ErrorCode.RESERVATION_NOT_FOUND, errorOf(() -> service.find(42)));
     }
+
+    @Test
+    void confirmationNotifiesHousekeepingAndFinance() {
+        Reservation reservation = service.create(stay(101, "2027-03-10", "2027-03-11", 1, RatePlan.STANDARD));
+
+        service.confirm(reservation.id());
+
+        List<Message> sent = sentMessages.all();
+        assertEquals(3, sent.size());
+        assertEquals("ana@example.com", sent.get(0).to());
+        assertEquals("Reserva confirmada - Pousada Maré Alta", sent.get(0).subject());
+        assertEquals("governanca@pousadamarealta.com.br", sent.get(1).to());
+        assertEquals("Reserva confirmada - quarto 101", sent.get(1).subject());
+        assertTrue(sent.get(1).body().contains("Entrada: 10/03/2027"));
+        assertTrue(sent.get(1).body().contains("Saída: 11/03/2027"));
+        assertTrue(sent.get(1).body().contains("Hóspedes: 1"));
+        assertEquals("financeiro@pousadamarealta.com.br", sent.get(2).to());
+        assertEquals("Pagamento recebido - reserva " + reservation.id(), sent.get(2).subject());
+        assertTrue(sent.get(2).body().contains("R$ 249,90"));
+    }
+
+    @Test
+    void cancellationOfConfirmedStandardReservationNotifiesHousekeepingAndFinance() {
+        Reservation reservation = service.create(stay(102, "2027-03-10", "2027-03-11", 1, RatePlan.STANDARD));
+        service.confirm(reservation.id());
+
+        service.cancel(reservation.id());
+
+        List<Message> sent = sentMessages.all();
+        assertEquals(5, sent.size()); // 3 for confirm + 2 for cancel
+        assertEquals("governanca@pousadamarealta.com.br", sent.get(3).to());
+        assertEquals("Reserva cancelada - quarto 102", sent.get(3).subject());
+        assertTrue(sent.get(3).body().contains("10/03/2027 a 11/03/2027"));
+        assertEquals("financeiro@pousadamarealta.com.br", sent.get(4).to());
+        assertEquals("Reembolso - reserva " + reservation.id(), sent.get(4).subject());
+        assertTrue(sent.get(4).body().contains("R$ 249,90"));
+    }
+
+    @Test
+    void nonRefundableCancellationDoesNotNotifyFinance() {
+        Reservation reservation = service.create(stay(201, "2027-03-10", "2027-03-11", 1, RatePlan.NON_REFUNDABLE));
+        service.confirm(reservation.id());
+
+        service.cancel(reservation.id());
+
+        List<Message> sent = sentMessages.all();
+        assertEquals(4, sent.size()); // 3 for confirm + 1 housekeeping notification (finance not notified)
+        assertEquals("governanca@pousadamarealta.com.br", sent.get(3).to());
+        assertEquals("Reserva cancelada - quarto 201", sent.get(3).subject());
+    }
+
+    @Test
+    void pendingCancellationDoesNotNotify() {
+        Reservation pending = service.create(stay(101, "2027-03-10", "2027-03-11", 1, RatePlan.STANDARD));
+
+        service.cancel(pending.id());
+
+        List<Message> sent = sentMessages.all();
+        assertEquals(0, sent.size());
+    }
 }
