    64	/** The life of a reservation: created, confirmed (paid), checked in, checked out, or cancelled. */
    65	public final class ReservationService {
    66	
    67	    static final String HOTEL_NAME = "Pousada Maré Alta";
    68	
    69	    private final Rooms rooms;
    70	    private final ReservationStore store;
    71	    private final PriceCalculator priceCalculator;
    72	    private final EmailSender emailSender;
    73	    private final List<ReservationEventNotifier> notifiers;
    74	
    75	    public ReservationService(
    76	            Rooms rooms, ReservationStore store, PriceCalculator priceCalculator, EmailSender emailSender) {
    77	        this(rooms, store, priceCalculator, emailSender, new ArrayList<>());
    78	    }
    79	
    80	    public ReservationService(
    81	            Rooms rooms,
    82	            ReservationStore store,
    83	            PriceCalculator priceCalculator,
    84	            EmailSender emailSender,
    85	            List<ReservationEventNotifier> notifiers) {
    86	        this.rooms = rooms;
    87	        this.store = store;
    88	        this.priceCalculator = priceCalculator;
    89	        this.emailSender = emailSender;
    90	        this.notifiers = notifiers;
    91	    }
    92	
    93	    public synchronized Reservation create(NewReservation request) {
    94	        if (!request.checkOut().isAfter(request.checkIn())) {
    95	            throw new HotelException(ErrorCode.INVALID_REQUEST, "check-out must be after check-in");
    96	        }
    97	        if (request.guests() < 1) {
    98	            throw new HotelException(ErrorCode.INVALID_REQUEST, "a reservation needs at least one guest");
    99	        }
   100	        Room room = rooms.find(request.roomNumber())
   101	                .orElseThrow(() -> new HotelException(
   102	                        ErrorCode.ROOM_NOT_FOUND, "room " + request.roomNumber() + " does not exist"));
   103	        if (request.guests() > room.capacity()) {
   104	            throw new HotelException(
   105	                    ErrorCode.CAPACITY_EXCEEDED,
   106	                    "room " + room.number() + " takes at most " + room.capacity() + " guests");
   107	        }
   108	        if (store.isRoomTaken(room.number(), request.checkIn(), request.checkOut())) {
   109	            throw new HotelException(
   110	                    ErrorCode.ROOM_UNAVAILABLE, "room " + room.number() + " is taken on some of those nights");
   111	        }
   112	        Price price = priceCalculator.calculate(room, request.checkIn(), request.checkOut(), request.ratePlan());
   113	        return store.add(request, price);
   114	    }
   115	
   116	    public Reservation find(long reservationId) {
   117	        return store.find(reservationId)
   118	                .orElseThrow(() -> new HotelException(
   119	                        ErrorCode.RESERVATION_NOT_FOUND, "reservation " + reservationId + " does not exist"));
   120	    }
   121	
   122	    /** The guest paid: the reservation is confirmed and the guest gets the receipt by e-mail. */
   123	    public synchronized Reservation confirm(long reservationId) {
   124	        Reservation reservation = find(reservationId);
   125	        if (reservation.status() != ReservationStatus.PENDING) {
   126	            throw notAllowed(reservation, "confirm");
   127	        }
   128	        reservation.confirmPayment();
   129	        store.update(reservation);
   130	        Room room = roomOf(reservation);
   131	        ReservationReceipt receipt = new ReservationReceipt(reservation, room);
   132	        emailSender.send(
   133	                reservation.guest().email(),
   134	                "Reserva confirmada - " + HOTEL_NAME,
   135	                confirmationEmailBody(reservation, receipt));
   136	        for (ReservationEventNotifier notifier : notifiers) {
   137	            notifier.notifyConfirmation(reservation, room);
   138	        }
   139	        return reservation;
   140	    }
   141	
   142	    /**
   143	     * Cancelling before the stay starts. What was paid comes back according to the rate plan (a pending
   144	     * reservation was never paid, so nothing comes back).
   145	     */
   146	    public synchronized Reservation cancel(long reservationId) {
   147	        Reservation reservation = find(reservationId);
   148	        if (reservation.status() != ReservationStatus.PENDING
   149	                && reservation.status() != ReservationStatus.CONFIRMED) {
   150	            throw notAllowed(reservation, "cancel");
   151	        }
   152	        boolean wasConfirmed = reservation.status() == ReservationStatus.CONFIRMED;
   153	        BigDecimal refund = switch (reservation.ratePlan()) {
   154	            case STANDARD -> reservation.amountPaid();
   155	            case NON_REFUNDABLE -> PriceCalculator.cents(BigDecimal.ZERO);
   156	        };
   157	        reservation.cancel(refund);
   158	        store.update(reservation);
   159	        if (wasConfirmed) {
   160	            Room room = roomOf(reservation);
   161	            for (ReservationEventNotifier notifier : notifiers) {
   162	                notifier.notifyCancellation(reservation, room);
   163	            }
   164	        }
   165	        return reservation;
   166	    }
   167	
   168	    public synchronized Reservation checkIn(long reservationId) {
   169	        Reservation reservation = find(reservationId);
   170	        if (reservation.status() != ReservationStatus.CONFIRMED) {
   171	            throw notAllowed(reservation, "check in");
   172	        }
   173	        reservation.changeStatus(ReservationStatus.CHECKED_IN);
   174	        store.update(reservation);
   175	        return reservation;
   176	    }
   177	
   178	    /** The guest leaves: the stay is closed and the final receipt is handed over. */
   179	    public synchronized ReservationReceipt checkOut(long reservationId) {
   180	        Reservation reservation = find(reservationId);
   181	        if (reservation.status() != ReservationStatus.CHECKED_IN) {
   182	            throw notAllowed(reservation, "check out");
   183	        }
   184	        reservation.changeStatus(ReservationStatus.CHECKED_OUT);
   185	        store.update(reservation);
   186	        return new ReservationReceipt(reservation, roomOf(reservation));
   187	    }
   188	
   189	    /** A copy of the receipt, for a guest who lost it. Only paid reservations have one. */
   190	    public ReservationReceipt receiptCopy(long reservationId) {
   191	        Reservation reservation = find(reservationId);
   192	        if (!reservation.isPaid()) {
   193	            throw notAllowed(reservation, "issue a receipt for");
   194	        }
   195	        return new ReservationReceipt(reservation, roomOf(reservation));
   196	    }
   197	
   198	    private Room roomOf(Reservation reservation) {
   199	        return rooms.find(reservation.roomNumber()).orElseThrow();
   200	    }
   201	
   202	    private static String confirmationEmailBody(Reservation reservation, ReservationReceipt receipt) {
   203	        return "Olá, " + reservation.guest().name() + "!\n\n"
   204	                + "Sua reserva na " + HOTEL_NAME + " está confirmada. Estes são os dados dela:\n\n"
   205	                + receipt.text() + "\n"
   206	                + "A entrada é a partir das 14h, e a saída, até as 12h.\n"
   207	                + "Até breve!\n";
   208	    }
   209	
   210	    private static HotelException notAllowed(Reservation reservation, String operation) {
   211	        return new HotelException(
   212	                ErrorCode.OPERATION_NOT_ALLOWED,
   213	                "cannot " + operation + " reservation " + reservation.id() + " while it is " + reservation.status());
   214	    }
   215	}
